<?php
 namespace PHPImageWorkshop; use PHPImageWorkshop\Core\ImageWorkshopLayer as ImageWorkshopLayer; use PHPImageWorkshop\Core\ImageWorkshopLib as ImageWorkshopLib; use PHPImageWorkshop\Exception\ImageWorkshopException; class ImageWorkshop { const ERROR_NOT_AN_IMAGE_FILE = 1; const ERROR_IMAGE_NOT_FOUND = 2; const ERROR_NOT_READABLE_FILE = 3; const ERROR_CREATE_IMAGE_FROM_STRING = 4; public static function initFromPath($path, $fixOrientation = false) { if (false === filter_var($path, FILTER_VALIDATE_URL) && !file_exists($path)) { throw new ImageWorkshopException(sprintf('File "%s" not exists.', $path), static::ERROR_IMAGE_NOT_FOUND); } if (false === ($imageSizeInfos = @getImageSize($path))) { throw new ImageWorkshopException('Can\'t open the file at "' . $path . '" : file is not readable, did you check permissions (755 / 777) ?', static::ERROR_NOT_READABLE_FILE); } $mimeContentType = explode('/', $imageSizeInfos['mime']); if (!isset($mimeContentType[1])) { $givenType = isset($mimeContentType[1]) ? $mimeContentType[1] : 'none'; throw new ImageWorkshopException('Not an image file (jpeg/png/gif) at "'.$path.'" (given format: "'.$givenType.'")', static::ERROR_NOT_AN_IMAGE_FILE); } $mimeContentType = $mimeContentType[1]; $exif = array(); switch ($mimeContentType) { case 'jpeg': $image = imageCreateFromJPEG($path); if (function_exists('exif_read_data') && false !== ($data = @exif_read_data($path))) { $exif = $data; } break; case 'gif': $image = imageCreateFromGIF($path); break; case 'png': $image = imageCreateFromPNG($path); break; case 'webp': $image = imagecreatefromwebp($path); break; default: throw new ImageWorkshopException('Not an image file (jpeg/png/gif) at "'.$path.'" (given format: "'.$mimeContentType.'")', static::ERROR_NOT_AN_IMAGE_FILE); } if (false === $image) { throw new ImageWorkshopException('Unable to create image with file found at "'.$path.'"'); } $layer = new ImageWorkshopLayer($image, $exif); if ($fixOrientation) { $layer->fixOrientation(); } return $layer; } public static function initTextLayer($text, $fontPath, $fontSize = 13, $fontColor = 'ffffff', $textRotation = 0, $backgroundColor = null) { $textDimensions = ImageWorkshopLib::getTextBoxDimension($fontSize, $textRotation, $fontPath, $text); $layer = static::initVirginLayer($textDimensions['width'], $textDimensions['height'], $backgroundColor); $layer->write($text, $fontPath, $fontSize, $fontColor, $textDimensions['left'], $textDimensions['top'], $textRotation); return $layer; } public static function initVirginLayer($width = 100, $height = 100, $backgroundColor = null) { $opacity = 0; if (null === $backgroundColor || $backgroundColor == 'transparent') { $opacity = 127; $backgroundColor = 'ffffff'; } return new ImageWorkshopLayer(ImageWorkshopLib::generateImage($width, $height, $backgroundColor, $opacity)); } public static function initFromResourceVar($image) { return new ImageWorkshopLayer($image); } public static function initFromString($imageString) { if (!$image = @imageCreateFromString($imageString)) { throw new ImageWorkshopException('Can\'t generate an image from the given string.', static::ERROR_CREATE_IMAGE_FROM_STRING); } return new ImageWorkshopLayer($image); } }